package com.prakash.gmcemp.shipment.model;import jakarta.persistence.*;import java.time.*;@Entity @Table(name="shipments") public class Shipment{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@Column(nullable=false,unique=true) private String bookingNo;private String vesselName;private String originPort;private String destinationPort;private String containerType;private Double cargoWeightTons;@Enumerated(EnumType.STRING) private ShipmentStatus status;private LocalDateTime createdAt;@PrePersist void pre(){createdAt=LocalDateTime.now();if(status==null)status=ShipmentStatus.CREATED;}public Long getId(){return id;}public void setId(Long v){id=v;}public String getBookingNo(){return bookingNo;}public void setBookingNo(String v){bookingNo=v;}public String getVesselName(){return vesselName;}public void setVesselName(String v){vesselName=v;}public String getOriginPort(){return originPort;}public void setOriginPort(String v){originPort=v;}public String getDestinationPort(){return destinationPort;}public void setDestinationPort(String v){destinationPort=v;}public String getContainerType(){return containerType;}public void setContainerType(String v){containerType=v;}public Double getCargoWeightTons(){return cargoWeightTons;}public void setCargoWeightTons(Double v){cargoWeightTons=v;}public ShipmentStatus getStatus(){return status;}public void setStatus(ShipmentStatus v){status=v;}public LocalDateTime getCreatedAt(){return createdAt;}}